(window.AUDIO_PAK = window.AUDIO_PAK || {})["je-kind-aanmelden"] = {"verteller|-10%|de klas": "data:audio/mpeg;base64,", "verteller|-10%|de juf": "data:audio/mpeg;base64,", "verteller|-10%|de meester": "data:audio/mpeg;base64,", "verteller|-10%|aanmelden": "data:audio/mpeg;base64,", "verteller|-10%|de groep": "data:audio/mpeg;base64,", "verteller|-10%|het schoolplein": "data:audio/mpeg;base64,", "verteller|-10%|de schooltas": "data:audio/mpeg;base64,", "verteller|-10%|Ik wil mijn zoon aanmelden.": "data:audio/mpeg;base64,", "verteller|-10%|Hij is zeven jaar.": "data:audio/mpeg;base64,", "verteller|-10%|In welke groep komt hij?": "data:audio/mpeg;base64,", "verteller|-10%|Wie is de juf?": "data:audio/mpeg;base64,", "verteller|-10%|Mag ik de klas zien?": "data:audio/mpeg;base64,", "marieke|-10%|Goedemorgen, welkom op school!": "data:audio/mpeg;base64,", "marieke|-10%|Leuk! Hoe oud is hij?": "data:audio/mpeg;base64,", "marieke|-10%|Dan komt hij in groep vier.": "data:audio/mpeg;base64,", "marieke|-10%|Natuurlijk. Kom maar mee.": "data:audio/mpeg;base64,", "verteller|-10%|het schooljaar": "data:audio/mpeg;base64,", "verteller|-10%|de ouders": "data:audio/mpeg;base64,", "verteller|-10%|de schooltijden": "data:audio/mpeg;base64,", "verteller|-10%|overblijven": "data:audio/mpeg;base64,", "verteller|-10%|de gymles": "data:audio/mpeg;base64,", "verteller|-10%|de bso": "data:audio/mpeg;base64,", "verteller|-10%|Wat zijn de schooltijden?": "data:audio/mpeg;base64,", "verteller|-10%|De school begint om half negen.": "data:audio/mpeg;base64,", "verteller|-10%|Mijn zoon blijft over op school.": "data:audio/mpeg;base64,", "verteller|-10%|Op dinsdag heeft hij gymles.": "data:audio/mpeg;base64,", "verteller|-10%|Na school gaat hij naar de bso.": "data:audio/mpeg;base64,", "marieke|-10%|Heeft u nog vragen?": "data:audio/mpeg;base64,", "marieke|-10%|Van half negen tot drie uur. Woensdag tot twaalf uur.": "data:audio/mpeg;base64,", "marieke|-10%|De kinderen blijven over. Ze nemen een broodtrommel mee.": "data:audio/mpeg;base64,", "marieke|-10%|Ja, op dinsdag heeft hij gymles.": "data:audio/mpeg;base64,", "marieke|-10%|Ja, de bso is naast de school.": "data:audio/mpeg;base64,", "marieke|-10%|Volgende maandag. Welkom op school!": "data:audio/mpeg;base64,", "verteller|-10%|de taalklas": "data:audio/mpeg;base64,", "verteller|-10%|de jeugdarts": "data:audio/mpeg;base64,", "verteller|-10%|het intakegesprek": "data:audio/mpeg;base64,", "verteller|-10%|Ik wil mijn dochter aanmelden.": "data:audio/mpeg;base64,", "verteller|-10%|Zij is zes jaar.": "data:audio/mpeg;base64,", "verteller|-10%|Op woensdag is de school om twaalf uur uit.": "data:audio/mpeg;base64,", "verteller|-10%|Ze gaat eerst naar de taalklas.": "data:audio/mpeg;base64,", "marieke|-10%|Goedemorgen! Hoe kan ik u helpen?": "data:audio/mpeg;base64,", "marieke|-10%|Hoe heet uw kind en hoe oud is het?": "data:audio/mpeg;base64,", "marieke|-10%|Spreekt uw kind al Nederlands?": "data:audio/mpeg;base64,", "marieke|-10%|Welke andere talen spreekt uw kind?": "data:audio/mpeg;base64,", "marieke|-10%|Heeft uw kind allergieën of medicijnen?": "data:audio/mpeg;base64,", "marieke|-10%|Dank u. Uw kind is van harte welkom!": "data:audio/mpeg;base64,", "marieke|+0%|Welkom, meneer. Vertelt u eens over uw dochter.": "data:audio/mpeg;base64,", "karim|+0%|Ze heet Noor en ze is acht jaar. Ze spreekt nog weinig Nederlands.": "data:audio/mpeg;base64,", "marieke|+0%|Dan gaat ze eerst een jaar naar de taalklas. Daarna komt ze in groep vijf.": "data:audio/mpeg;base64,", "karim|+0%|Is de taalklas hier op school?": "data:audio/mpeg;base64,", "marieke|+0%|Nee, in een andere school. Er rijdt een busje voor de kinderen.": "data:audio/mpeg;base64,", "karim|+0%|Moet ze ook naar de dokter?": "data:audio/mpeg;base64,", "marieke|+0%|Ja, de jeugdarts nodigt alle nieuwe kinderen uit. U krijgt een brief.": "data:audio/mpeg;base64,", "karim|+0%|Goed, dank u wel voor de uitleg.": "data:audio/mpeg;base64,", "marieke|-10%|Vul de gegevens van uw kind in.": "data:audio/mpeg;base64,", "verteller|-10%|Mijn zoon heet Adam. Hij is zeven jaar. Hij spreekt Arabisch en een beetje Nederlands.": "data:audio/mpeg;base64,"};
